// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new MY_BANK(address(lg));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(lg) && actor != address(this));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);

        bool ok;
        vm.prank(actor);
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: every successful Put is recorded: History gains an entry with
        // Sender == caller and Val == amount deposited.
        bool recorded = !ok; // no Put => vacuously satisfied
        if (ok) {
            try lg.History(0) returns (address sender, string memory, uint256 val, uint256) {
                recorded = (sender == actor && val == amount);
            } catch {
                recorded = false;
            }
        }
        assertTrue(recorded);
    }
}
